// Code by Flopine

// Thanks to wsmind, leon, XT95, lsdlive, lamogui, 
// Coyhot, Alkama,YX, NuSan, slerpy, wwrighter 
// BigWings, FabriceNeyret and Blackle for teaching me

// Thanks LJ for giving me the spark :3

// Thanks to the Cookie Collective, which build a cozy and safe environment for me 
// and other to sprout :)  
// https://twitter.com/CookieDemoparty

// Genuary #06: Make a landscape using only primitive shapes


#define PI acos(-1.)
#define TAU (2.*PI)
#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a))

#define noi(u) textureLod(iChannel0, u, 0.).x
#define crep(p,c,l) p -= c*clamp(round(p/c), -l, l)

void moda(inout vec2 p, float rep)
{
    float per = TAU/rep;
    float a = mod(atan(p.x, p.y)+per*.5, per)-per*.5;
    p = vec2(cos(a), sin(a))*length(p);
}

vec2 edge (vec2 p)
{
    vec2 p2=abs(p);
    return (p2.x>p2.y) ? vec2((p.x<0.) ? -1. : 1., 0.) : vec2(0., (p.y<0.) ? -1. : 1.);
}

float box (vec3 p, vec3 c)
{
    vec3 q = abs(p)-c;
    return min(0., max(q.x, max(q.y, q.z)))+length(max(q, 0.));
}

float prim (vec3 p, vec3 s)
{
    float d = box(p, s);

    float rep = s.y *.25;
    float limit = ceil(s.y)+1.;
    crep(p.y, rep, limit);    
    moda(p.xz, 4.);
    p.x -= s.x;

    d = max(d, -box(p, vec3(s.x*.4, s.y*.08, s.z*.6)));

    return d;
}

float g1 = 0.;
float SDF (vec3 p)
{
    p.yz  *= rot(-atan(1./sqrt(2.)));
    p.xz *= rot(PI/4.);

    float ground = abs(p.y)-.05;
    g1 += 0.1/(0.1+ground*ground);

    vec2 center = round(p.xz);
    vec2 neighbour = center+edge(p.xz-center);

    float high = mix(.3, 5., noi(center*.13));
    float thick = mix(.1, .45, noi(center*.43));
    float me = prim(p-vec3(center.x, 0., center.y),vec3(thick, high, .45));
    float ne = box(p-vec3(neighbour.x, 0., neighbour.y), vec3(.45, 5., .45));

    return min(me,ne);
}


vec3 gn (vec3 p)
{
    vec2 eps = vec2(0.001, 0.);
    return normalize(SDF(p)-vec3(SDF(p-eps.xyy),SDF(p-eps.yxy),SDF(p-eps.yyx)));
}

float AO (vec3 p, vec3 n, float e)
{return clamp(SDF(p+e*n)/e,0., 1.);}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2.*fragCoord-iResolution.xy)/iResolution.y;

    vec3 ro = vec3(uv*6., -30.), rd=vec3(0.,0.,1.), p=ro,
    col=vec3(0.), l=normalize(vec3(1., 2., -1.5));

    bool hit = false;
    for (float i=0.; i<100.; i++)
    {
        float d = SDF(p);
        if (d<0.001)
        {
            hit=true;
            break;
        }
        p += d*rd;
    }

    if (hit)
    {
        vec3 n = gn(p);
        float ao = AO(p,n, 0.15)+AO(p,n, 0.25)+AO(p,n, 0.3);
        col = vec3(0.02,0.04,0.1)*ao/3.;
    }

    float flash = mix(.1, .4, smoothstep(.4, .6, noi(p.xz*.001)));
    col += g1*vec3(1., .45, 0.)*exp(-fract(iTime*5.)*.15)*flash;

    fragColor = vec4(sqrt(col),1.0);
}
